    var cherryToday = maw.filter(function (m) { return (deliveriesBy0(m.id)).some(function (d) { return d.delivered_on === TODAY && d.product === "cp-maw-cherry"; }); }).slice(0, 6);
    function deliveriesBy0(id) { return deliveries.filter(function (d) { return d.member === id; }); }
